//! The compiler's stack limit (design §5.6), after `Zend/zend_call_stack.c`
//! and the check `zend_compile.c` makes under `ZEND_CHECK_STACK_LIMIT`:
//! the compiler recurses on the tree, one native frame per node, and a
//! tree deep enough would take the thread down with it. php reads two
//! ini entries, `zend.max_allowed_stack_size` and
//! `zend.reserved_stack_size`, works a limit address out of them once
//! per thread (`zend_call_stack_init`), and compares a local's address to
//! it at the top of `zend_compile_expr`, `zend_compile_var`,
//! `zend_delayed_compile_var` and `zend_eval_const_expr`; past the limit
//! it raises `E_COMPILE_ERROR` with php's sentence, and the request ends
//! there instead of in a signal. What is here is that pair of addresses
//! and that comparison; the engine builds one per request, on the
//! request's thread, and hands it to the compiler in
//! [`crate::Options`].
//!
//! The thread's own bounds are php's reading too. `zend_call_stack_get`
//! asks the platform for the calling thread's base and size, and this
//! crate forbids `unsafe`, so the asking is `php_heap`'s,
//! [`php_heap::call_stack_bounds`], read through `heap.lock`; the
//! native stack is the host's thread's, whatever size the host gave it,
//! and the engine sizes no thread of its own (design §5.6, §5.14). A
//! thread the platform cannot describe gets php's own fallback, the
//! `ZEND_MAX_ALLOWED_STACK_SIZE_DETECT` arm of `zend_call_stack_init`
//! where `base` is null: the address of a local at init as the base,
//! which "is not the actual stack base", and the size php assumes for
//! the platform, [`php_heap::call_stack_default_size`], less 32 KiB for
//! the distance already walked; the limit is then an estimate, as php's
//! is there. A host thread smaller than a program needs is not refused
//! at `serve`: the limit is what the thread has, and a nesting past it
//! is the same fatal php raises on the same thread, earlier.

use php_heap::{call_stack_bounds, call_stack_default_size};
use php_unit::Level;

use crate::CompileError;

/// `EG(stack_base)` and `EG(stack_limit)`, the two addresses
/// `zend_call_stack_init` leaves for the thread: both zero where nothing
/// is checked, which is what `zend.max_allowed_stack_size=-1` asks for.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct StackLimit {
    base: usize,
    limit: usize,
}

/// `ZEND_MAX_ALLOWED_STACK_SIZE_DETECT`, the entry's default.
const DETECT: i64 = 0;

/// `ZEND_ALLOCA_MAX_SIZE + 16*1024`, the least `zend.reserved_stack_size`
/// php takes on a platform with `alloca`, which the two the oracle runs on
/// are: room for one `alloca`, PCRE2's start frames and a few plain
/// calls below the check (`OnUpdateReservedStackSize`).
const RESERVED_MIN: u64 = 32 * 1024 + 16 * 1024;

impl StackLimit {
    /// The `ZEND_MAX_ALLOWED_STACK_SIZE_UNCHECKED` arm: no base and no
    /// limit, so [`check`](Self::check) never refuses. What
    /// [`crate::Options::default`] carries, since a caller that says
    /// nothing of its thread has told the compiler nothing to hold it to.
    pub const UNCHECKED: StackLimit = StackLimit { base: 0, limit: 0 };

    /// `zend_call_stack_init` on the calling thread, from the two ini
    /// entries as the engine parsed them: `max_allowed` is
    /// `zend.max_allowed_stack_size`, `-1` unchecked, `0` detect and a
    /// positive number the size to allow from here; `reserved` is
    /// `zend.reserved_stack_size`, `0` for php's minimum, which a smaller
    /// number is raised to as php's `OnUpdate` handler refuses it.
    ///
    /// Detect reads the thread's bounds as the platform describes them,
    /// `php_heap::call_stack_bounds`; on a thread it cannot describe,
    /// the base is where this frame stands and the size is
    /// `php_heap::call_stack_default_size` less the 32 KiB php allows
    /// for the frames already below the real base. A positive number is
    /// the size to allow below the base the platform read, or below
    /// this frame where it read none.
    #[must_use]
    pub fn init(max_allowed: i64, reserved: u64) -> StackLimit {
        let reserved = reserved.max(RESERVED_MIN);
        let reserved = usize::try_from(reserved).unwrap_or(usize::MAX);
        let read = call_stack_bounds();
        let base = read.map_or_else(position, |stack| stack.base);
        match max_allowed {
            DETECT => {
                let size = read.map_or_else(
                    || call_stack_default_size().saturating_sub(32 * 1024),
                    |stack| stack.max_size,
                );
                StackLimit {
                    base,
                    limit: limit(base, size, reserved),
                }
            }
            allowed if allowed > 0 => {
                let size = usize::try_from(allowed).unwrap_or(usize::MAX);
                StackLimit {
                    base,
                    limit: limit(base, size, reserved),
                }
            }
            _ => StackLimit::UNCHECKED,
        }
    }

    /// `zend_check_stack_limit`: nothing while the calling frame stands
    /// above the limit, and past it php's `E_COMPILE_ERROR`
    /// (`zend_stack_limit_error`), whose number is the distance from the
    /// base to the limit, `zend.max_allowed_stack_size` less
    /// `zend.reserved_stack_size` as the message says.
    ///
    /// A left-nested chain is one node deeper per link and no deeper
    /// for the parser, so php's grammar takes it whole and php's
    /// compiler refuses it here, at about fifty thousand links under an
    /// 8 MiB stack, where twenty thousand nested parentheses are the
    /// parser's `memory exhausted`. The number is the thread's, read
    /// from the platform by both engines and so the rlimit's under the
    /// shell that runs them, so the witness masks it; the sentence, the
    /// file and the line are pinned. Two hundred thousand links is #246's measurement, room
    /// for a stack four times the default.
    ///
    /// ```php
    /// $y = ;
    /// echo 'never';
    /// ```
    /// ```expect exit=255
    /// Fatal error: Maximum call stack size of %d bytes (zend.max_allowed_stack_size - zend.reserved_stack_size) reached during compilation. Try splitting expression in %s on line 2
    /// ```
    pub(crate) fn check(&self, line: u32) -> Result<(), CompileError> {
        // `zend_call_stack_overflowed`.
        if position() > self.limit {
            return Ok(());
        }
        let max_stack_size = self.base.saturating_sub(self.limit);
        Err(CompileError {
            level: Level::CompileError,
            message: format!(
                "Maximum call stack size of {max_stack_size} bytes (zend.max_allowed_stack_size - zend.reserved_stack_size) reached during compilation. Try splitting expression"
            ),
            line,
            raised: Vec::new(),
        })
    }
}

/// `zend_call_stack_limit`: the address `size` bytes below `base` and
/// `reserved` above that, zero where the size is more than the address
/// itself and the top of memory where the reservation would wrap.
fn limit(base: usize, size: usize, reserved: usize) -> usize {
    if size > base {
        return 0;
    }
    let base = base - size;
    if usize::MAX - base < reserved {
        return usize::MAX;
    }
    base + reserved
}

/// `zend_call_stack_position`: the address of a local of the calling
/// frame, php's `__builtin_frame_address(0)`. Stacks grow down, so a
/// deeper frame is a smaller address.
#[inline]
fn position() -> usize {
    let here = 0u8;
    std::ptr::addr_of!(here).addr()
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A limit that allows nothing beyond the reservation refuses the
    /// next frame down, with php's number in php's sentence.
    #[test]
    fn a_limit_at_the_base_refuses_the_next_frame() {
        let stack = StackLimit::init(1, 0);
        let refused = deeper(&stack).err();
        assert_eq!(refused.as_ref().map(|e| e.level), Some(Level::CompileError));
        assert_eq!(refused.as_ref().map(|e| e.line), Some(2));
        // `limit` clamps a size smaller than the reservation to the
        // reservation above the base less one.
        assert!(
            refused.is_some_and(|e| e.message.starts_with("Maximum call stack size of ")
                && e.message.ends_with(
                    " bytes (zend.max_allowed_stack_size - zend.reserved_stack_size) reached during compilation. Try splitting expression"
                )),
        );
    }

    /// `-1` is unchecked, and so is a default `Options`.
    #[test]
    fn minus_one_is_unchecked() {
        assert_eq!(StackLimit::init(-1, 0), StackLimit::UNCHECKED);
        assert!(deeper(&StackLimit::UNCHECKED).is_ok());
        assert_eq!(crate::Options::default().stack, StackLimit::UNCHECKED);
    }

    /// Detect on a test thread leaves room for a frame, and a size a
    /// frame fits in does too: the size php prints is the size allowed
    /// less the reservation.
    #[test]
    fn the_number_is_the_size_less_the_reservation() {
        let stack = StackLimit::init(1024 * 1024, 0);
        assert!(deeper(&stack).is_ok());
        assert_eq!(
            stack.base - stack.limit,
            1024 * 1024 - usize::try_from(RESERVED_MIN).unwrap_or(0)
        );
        let reserved = StackLimit::init(1024 * 1024, 100 * 1024);
        assert_eq!(reserved.base - reserved.limit, 924 * 1024);
        assert!(deeper(&StackLimit::init(0, 0)).is_ok());
    }

    /// Detect reads the thread the limit is built on: on a thread
    /// spawned at one size, the number is that size less the
    /// reservation, to the page, and the base is above every local of
    /// the thread. On a platform this engine has no arm for, the
    /// fallback's number is the assumed size less php's 32 KiB.
    #[test]
    fn detect_reads_the_calling_threads_bounds() {
        let size = 1024 * 1024;
        let Ok(spawned) = std::thread::Builder::new().stack_size(size).spawn(|| {
            let stack = StackLimit::init(0, 0);
            (stack, position())
        }) else {
            return;
        };
        let Ok((stack, local)) = spawned.join() else {
            return;
        };
        let reserved = usize::try_from(RESERVED_MIN).unwrap_or(0);
        let read = stack.base - stack.limit + reserved;
        if php_heap::call_stack_bounds().is_none() {
            assert_eq!(read, php_heap::call_stack_default_size() - 32 * 1024);
            return;
        }
        assert!(
            read >= size && read < 2 * size,
            "a {size}-byte thread reads as {read}"
        );
        assert!(local < stack.base && local > stack.limit);
    }

    /// `limit`'s two clamps.
    #[test]
    fn a_size_past_the_address_and_a_reservation_past_memory_clamp() {
        assert_eq!(limit(100, 200, 10), 0);
        assert_eq!(limit(usize::MAX - 10, 5, 100), usize::MAX);
        assert_eq!(limit(1000, 200, 50), 850);
    }

    /// One frame below the caller, which is where the compiler checks.
    #[inline(never)]
    fn deeper(stack: &StackLimit) -> Result<(), CompileError> {
        std::hint::black_box(stack).check(2)
    }
}
